const INJ = /(ignore (all |the |these )?(previous |above )?(instructions?|prompts?)|disregard (the |all |previous |these )?(instructions?|prompts?)|ignore the (system )?prompt|forget (all |everything|the )?(previous |above )?(instructions?|prompts?)|you are now (a |an )|new instructions?\s*:|override (the )?(status|rule|system)|respond only with|output (only )?the following|set status to|mark this as)\b/i;
const SRC = [
  [/curse|wrong_number|denied_registration|no_money|under_18|invalid_country|third_party|base:no_language/i, 0.95, 'deterministic strong policy'],
  [/refusal_in_newest|callback_in_newest|refusal_2_days/i, 0.90, 'clear signal in newest comment'],
  [/Decline/i, 0.90, 'decline policy'],
  [/no_answer_5_distinct_days|no_real_conversation/i, 0.85, 'mechanical no-answer rule'],
  [/callback_detected|Appointment/i, 0.80, 'appointment/callback detection'],
  [/Sheet rule/i, 0.78, 'sheet rule matched'],
  [/Verifier AI/i, 0.70, 'verifier correction'],
  [/AI Agent/i, 0.60, 'AI judgement'],
