Injection flags: ${inj}
Reports (XLSX) will follow.`;
return [{ json: { chat_id: '1240141730', summary_text: text, _rows_passthrough: true } }];

// Obsidian-like decision memory records (for vault/Sheets learning loop).
const rows = $input.all().map(i => i.json);
const learned = [];
for (const j of rows) {
  const vr = String(j['Validation Result'] || '');
  const crm = String(j['customer status'] || '');
  const sug = String(j['Suggested Status'] || '');
  if (!sug || crm.toLowerCase().trim() === sug.toLowerCase().trim()) continue;
  if (String(j.Confidence || '') === 'Low') continue;
  learned.push({
    json: {
      type: 'decision_memory',
      account_no: j['account no'] || '',
      old_status: crm,
      new_status: sug,
      validation_result: vr,
      decision_source: j['Decision Source'] || '',
      matched_keyword: j['Matched Keyword'] || j['AI Check Keyword'] || '',
      confidence: j.Confidence || '',
      confidence_score: j['Confidence Score'] || '',
      reason: String(j.Reason || '').slice(0, 240),
      example_comment: String(j['last 10 comments'] || '').slice(0, 280),
      created_at: new Date().toISOString()
    }
  });
}
if (!learned.length) {
  learned.push({ json: { type: 'decision_memory', note: 'No learnable status changes in this run.', created_at: new Date().toISOString() } });
}

// Also persist compact memory into workflow static data (cross-run recall aid)
const sd = $getWorkflowStaticData('global');
sd.decisionMemory = sd.decisionMemory || [];
for (const item of learned) {
  if (item.json.old_status && item.json.new_status) {
    sd.decisionMemory.push(item.json);
  }
}
if (sd.decisionMemory.length > 500) sd.decisionMemory = sd.decisionMemory.slice(-500);
return learned;

// Track sheet-rule hit counts in workflow static data (self-improving priority signal).
const sd = $getWorkflowStaticData('global');
sd.ruleHits = sd.ruleHits || {};
const out = $input.all().map(it => {
  const j = { ...it.json };
  const key = String(j['Matched Keyword'] || j.matched_trigger || '').trim().toLowerCase();
  if (key) {
    sd.ruleHits[key] = (sd.ruleHits[key] || 0) + 1;
    j['Rule Hit Count'] = sd.ruleHits[key];
  } else {
    j['Rule Hit Count'] = 0;
  }
  return { json: j };
});
return out;
